    public static int TtIou(int ax0, int ay0, int ax1, int ay1, int bx0, int by0, int bx1, int by1) {
        // The intersection over union of two boxes (cp), per mille. Areas in tenths of a point so they fit.
        int iw = TtMax(0, TtMin(ax1, bx1) - TtMax(ax0, bx0)) / 10;
        int ih = TtMax(0, TtMin(ay1, by1) - TtMax(ay0, by0)) / 10;
        int inter = iw * ih;
        int aa = (TtMax(0, ax1 - ax0) / 10) * (TtMax(0, ay1 - ay0) / 10);
        int ab = (TtMax(0, bx1 - bx0) / 10) * (TtMax(0, by1 - by0) / 10);
        int un = (aa + ab) - inter;
        if (un <= 0) {
            return 0;
        }
        return TtPm(inter, un);
    }
    internal static int TtMode(emon.Port.Cells ws, int at0, int n, int m, int i) {
        // The column of the matrix at ws[base..] (n rows of m) with the most words in row i; -1 when the row has none; ties go to the
        // lowest column.
        int j = 0;
        int best = -1;
        int bv = 0;
        while (j < m) {
            if (emon.Port.CellsAt(ws, at0 + ((i * m) + j)) > bv) {
                bv = emon.Port.CellsAt(ws, at0 + ((i * m) + j));
                best = j;
            }
            j += 1;
        }
        return best;
    }
    public static int TtGeoMap(emon.Port.Cells tg, int k, emon.Port.Cells ta, emon.Port.Cells wo, int w0, emon.Port.Cells tb, int t, emon.Port.Cells tc, emon.Port.Cells tw, emon.Port.Cells ws) {
        // The majority mapping of table k's rows and columns onto candidate t of `tb` (stride 28, cells of stride 16): ws[0..nrows) is the
        // candidate row of each tagged row, ws[nrows..nrows+ncols) the candidate column of each tagged column (-1 none). Answers the words
        // that agree: the tagged row and column map one-to-one and a word's candidate cell is the one they name; -2 when the matrices
        // would not fit (more than a million cells), and the arena is left as the maps. The words' cells are in `ws` after the maps.
        int b = k * Tgs;
        int cf = emon.Port.CellsAt(tg, b + 4);
        int ce = cf + emon.Port.CellsAt(tg, b + 5);
        int nr = emon.Port.CellsAt(tg, b + 2);
        int nc = emon.Port.CellsAt(tg, b + 3);
        int tb0 = t * 28;
        int gnr = emon.Port.CellsAt(tb, tb0 + 7);
        int gnc = emon.Port.CellsAt(tb, tb0 + 8);
        int gcf = emon.Port.CellsAt(tb, tb0 + 9);
        int gce = gcf + emon.Port.CellsAt(tb, tb0 + 10);
        int nw = emon.Port.CellsLen(wo) / 1;
        int i = 0;
        int j = 0;
        int g = 0;
        int wi = 0;
        int cell = 0;
        int tr = 0;
        int tcc = 0;
        int gr = 0;
        int gc = 0;
        int agree = 0;
        int mv = 0;
        int dup = 0;
        int ob = 0;
        int lo = 0;
        int hi = 0;
        int rowok = 0;
        int multi = 0;
        emon.Port.CellsDrop(ws, 0);
        if (((nr * gnr) + (nc * gnc)) > 1000000) {
            return -2;
        }
        i = 0;
        while (i < (nr + nc)) {
            emon.Port.CellsPush(ws, -1);
            i += 1;
        }
        i = 0;
        while (i < (nw * 2)) {
            emon.Port.CellsPush(ws, -1);
            i += 1;
        }
        i = 0;
        while (i < ((nr * gnr) + (nc * gnc))) {
            emon.Port.CellsPush(ws, 0);
            i += 1;
        }
        g = gcf;
        while (g < gce) {
            i = emon.Port.CellsAt(tc, (g * 16) + 9);
            j = 0;
            while (j < i) {
                wi = emon.Port.CellsAt(tw, emon.Port.CellsAt(tc, (g * 16) + 8) + j) - w0;
                if ((wi >= 0) && (wi < nw)) {
                    emon.Port.CellsSet(ws, (nr + nc) + (wi * 2), emon.Port.CellsAt(tc, g * 16));
                    emon.Port.CellsSet(ws, ((nr + nc) + (wi * 2)) + 1, emon.Port.CellsAt(tc, (g * 16) + 1));
                }
                j += 1;
            }
            g += 1;
        }
        wi = 0;
        while (wi < nw) {
            cell = emon.Port.CellsAt(wo, wi);
            if ((cell >= cf) && (cell < ce)) {
                tr = emon.Port.CellsAt(ta, (cell * Tas) + 1);
                tcc = emon.Port.CellsAt(ta, (cell * Tas) + 2);
                gr = emon.Port.CellsAt(ws, (nr + nc) + (wi * 2));
                gc = emon.Port.CellsAt(ws, ((nr + nc) + (wi * 2)) + 1);
                if ((gr >= 0) && ((gc >= 0) && ((tr < nr) && ((tcc < nc) && ((gr < gnr) && (gc < gnc)))))) {
                    emon.Port.CellsSet(ws, ((nr + nc) + (nw * 2)) + ((tr * gnr) + gr), emon.Port.CellsAt(ws, ((nr + nc) + (nw * 2)) + ((tr * gnr) + gr)) + 1);
                    emon.Port.CellsSet(ws, (((nr + nc) + (nw * 2)) + (nr * gnr)) + ((tcc * gnc) + gc), emon.Port.CellsAt(ws, (((nr + nc) + (nw * 2)) + (nr * gnr)) + ((tcc * gnc) + gc)) + 1);
                }
            }
            wi += 1;
        }
        i = 0;
        while (i < nr) {
            mv = TtMode(ws, (nr + nc) + (nw * 2), nr, gnr, i);
            emon.Port.CellsSet(ws, i, mv);
            i += 1;
        }
        i = 0;
        while (i < nc) {
            mv = TtMode(ws, ((nr + nc) + (nw * 2)) + (nr * gnr), nc, gnc, i);
            emon.Port.CellsSet(ws, nr + i, mv);
            i += 1;
        }
        i = 0;
        while (i < nr) {
            j = 0;
            dup = 0;
            while (j < nr) {
                if ((j != i) && ((emon.Port.CellsAt(ws, i) >= 0) && (emon.Port.CellsAt(ws, j) == emon.Port.CellsAt(ws, i)))) {
                    dup = 1;
                }
                j += 1;
            }
            if (dup == 1) {
                emon.Port.CellsSet(ws, i, 0 - 2);
            }
            i += 1;
        }
        i = 0;
        while (i < nc) {
            j = 0;
            dup = 0;
            while (j < nc) {
                if ((j != i) && ((emon.Port.CellsAt(ws, nr + i) >= 0) && (emon.Port.CellsAt(ws, nr + j) == emon.Port.CellsAt(ws, nr + i)))) {
                    dup = 1;
                }
                j += 1;
            }
            if (dup == 1) {
                emon.Port.CellsSet(ws, nr + i, 0 - 2);
            }
            i += 1;
        }
        ob = emon.Port.CellsLen(ws);
        g = 0;
        while (g < gnr) {
            mv = -1;
            dup = 0;
            i = 0;
            while (i < nr) {
                if (emon.Port.CellsAt(ws, ((nr + nc) + (nw * 2)) + ((i * gnr) + g)) > dup) {
                    dup = emon.Port.CellsAt(ws, ((nr + nc) + (nw * 2)) + ((i * gnr) + g));
                    mv = i;
                }
                i += 1;
            }
            emon.Port.CellsPush(ws, mv);
            g += 1;
        }
        i = 0;
        while (i < nr) {
            lo = -1;
            hi = -1;
            g = 0;
            while (g < gnr) {
                if (emon.Port.CellsAt(ws, ob + g) == i) {
                    if (lo < 0) {
                        lo = g;
                    }
                    hi = g;
                }
                g += 1;
            }
            g = lo;
            while ((lo >= 0) && (g <= hi)) {
                mv = emon.Port.CellsAt(ws, ob + g);
                if ((mv >= 0) && (mv != i)) {
                    lo = -1;
                    hi = -1;
                }
                g += 1;
            }
            emon.Port.CellsPush(ws, lo);
            emon.Port.CellsPush(ws, hi);
            i += 1;
        }
        wi = 0;
        while (wi < nw) {
            cell = emon.Port.CellsAt(wo, wi);
            if ((cell >= cf) && (cell < ce)) {
                tr = emon.Port.CellsAt(ta, (cell * Tas) + 1);
                tcc = emon.Port.CellsAt(ta, (cell * Tas) + 2);
                if ((tr < nr) && (tcc < nc)) {
                    if (emon.Port.CellsAt(ws, nr + tcc) >= 0) {
                        if (emon.Port.CellsAt(ws, nr + tcc) == emon.Port.CellsAt(ws, ((nr + nc) + (wi * 2)) + 1)) {
                            gr = emon.Port.CellsAt(ws, (nr + nc) + (wi * 2));
                            rowok = 0;
                            if ((emon.Port.CellsAt(ws, tr) >= 0) && (emon.Port.CellsAt(ws, tr) == gr)) {
                                rowok = 1;
                            }
                            if ((rowok == 0) && ((gr >= 0) && ((emon.Port.CellsAt(ws, (ob + gnr) + (tr * 2)) >= 0) && ((gr >= emon.Port.CellsAt(ws, (ob + gnr) + (tr * 2))) && (gr <= emon.Port.CellsAt(ws, ((ob + gnr) + (tr * 2)) + 1)))))) {
                                if (emon.Port.CellsAt(ws, ob + gr) == tr) {
                                    rowok = 1;
                                    multi = 1;
                                }
                            }
                            if (rowok == 1) {
                                agree += 1;
                            }
                        }
                    }
                }
            }
            wi += 1;
        }
        emon.Port.CellsPush(ws, multi);
        return agree;
    }
    public static int TtGeoTb(emon.Port.Cells tg, int k, emon.Port.Cells tb, int t0, int t1) {
        // The candidate of tb t0..t1 (not a struct one) whose box overlaps table k's at IoU 500 or more, the best; -1 when none (or when the
        // table owns no word, so has no box).
        int b = k * Tgs;
        int t = t0;
        int best = -1;
        int bv = 499;
        int v = 0;
        if (emon.Port.CellsAt(tg, b + 14) == 0) {
            return -1;
        }
        while (t < t1) {
            if (emon.Port.CellsAt(tb, (t * 28) + 5) != 5) {
                v = TtIou(emon.Port.CellsAt(tg, b + 6), emon.Port.CellsAt(tg, b + 7), emon.Port.CellsAt(tg, b + 8), emon.Port.CellsAt(tg, b + 9), emon.Port.CellsAt(tb, (t * 28) + 1), emon.Port.CellsAt(tb, (t * 28) + 2), emon.Port.CellsAt(tb, (t * 28) + 3), emon.Port.CellsAt(tb, (t * 28) + 4));
                if (v > bv) {
                    bv = v;
                    best = t;
                }
            }
            t += 1;
        }
        return best;
    }
    internal static int TtHv(int v, int w, emon.Port.Cells acc) {
        // Add a check to the harmonic mean (acc: weights, weight / value in millionths, the weakest): -1 is left out, a value is floored at 50.
        if (v < 0) {
            return 0;
        }
        emon.Port.CellsSet(acc, 0, emon.Port.CellsAt(acc, 0) + w);
        emon.Port.CellsSet(acc, 1, emon.Port.CellsAt(acc, 1) + ((w * 1000000) / TtMax(v, 50)));
        if (v < emon.Port.CellsAt(acc, 2)) {
            emon.Port.CellsSet(acc, 2, v);
        }
        return 0;
    }
    public static int TtScore(emon.Port.Cells tg, int k, emon.Port.Cells acc) {
        // D150's shape over the six checks (weights 2 2 1 2 2 3): the weighted harmonic mean, scaled by (1000 + the weakest) / 2000; the
        // verdict is confirmed at `tb-struct-ok`, contradicted under `tb-struct-bad`, else partial. A table with nothing to check scores 0.
        int b = k * Tgs;
        int score = 0;
        emon.Port.CellsDrop(acc, 0);
        emon.Port.CellsPush(acc, 0);
        emon.Port.CellsPush(acc, 0);
        emon.Port.CellsPush(acc, 1000);
        TtHv(emon.Port.CellsAt(tg, b + 16), 2, acc);
        TtHv(emon.Port.CellsAt(tg, b + 17), 2, acc);
        TtHv(emon.Port.CellsAt(tg, b + 18), 1, acc);
        TtHv(emon.Port.CellsAt(tg, b + 19), 2, acc);
        TtHv(emon.Port.CellsAt(tg, b + 20), 2, acc);
        TtHv(emon.Port.CellsAt(tg, b + 21), 3, acc);
        if (emon.Port.CellsAt(acc, 1) > 0) {
            score = (emon.Port.CellsAt(acc, 0) * 1000000) / emon.Port.CellsAt(acc, 1);
            score = (score * (1000 + emon.Port.CellsAt(acc, 2))) / 2000;
        }
        if (score > 1000) {
            score = 1000;
        }
        emon.Port.CellsSet(tg, b + 11, score);
        emon.Port.CellsSet(tg, b + 10, 2);
        if (score >= TbStructOk) {
            emon.Port.CellsSet(tg, b + 10, 1);
        }
        if (score < TbStructBad) {
            emon.Port.CellsSet(tg, b + 10, 3);
        }
        return score;
    }
    internal static int TtEmitVerdict(System.Text.StringBuilder t, int v) {
        if (v == 1) {
            emon.Port.TextAscii(t, "confirmed");
        }
        if (v == 2) {
            emon.Port.TextAscii(t, "partial");
        }
        if (v == 3) {
            emon.Port.TextAscii(t, "contradicted");
        }
        if (v == 0) {
            emon.Port.TextAscii(t, "none");
        }
        return 0;
    }
    public static int TtEmit(System.Text.StringBuilder t, emon.Port.Cells tv) {
        // The document's tagged-table verdicts as a JSON array, `[{"page":1,"se":N,"rows":R,"cols":C,"verdict":"confirmed",
        // "score":S,"checks":[row-band,col-band,order,cover,rules,geo],"trust":T},...]`; these are the evidence dump's `tb` (SPEC 9.7).
        int n = emon.Port.CellsLen(tv) / Tvs;
        int i = 0;
        int j = 0;
        emon.Port.TextAscii(t, "[");
        while (i < n) {
            if (i > 0) {
                emon.Port.TextAscii(t, ",");
            }
            emon.Port.TextAscii(t, "{\"page\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(tv, i * Tvs));
            emon.Port.TextAscii(t, ",\"se\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(tv, (i * Tvs) + 1));
            emon.Port.TextAscii(t, ",\"rows\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(tv, (i * Tvs) + 2));
            emon.Port.TextAscii(t, ",\"cols\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(tv, (i * Tvs) + 3));
            emon.Port.TextAscii(t, ",\"verdict\":\"");
            TtEmitVerdict(t, emon.Port.CellsAt(tv, (i * Tvs) + 4));
            emon.Port.TextAscii(t, "\",\"score\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(tv, (i * Tvs) + 5));
            emon.Port.TextAscii(t, ",\"checks\":[");
            j = 0;
            while (j < 6) {
                if (j > 0) {
                    emon.Port.TextAscii(t, ",");
                }
                emon.Port.TextI32(t, emon.Port.CellsAt(tv, ((i * Tvs) + 6) + j));
                j += 1;
            }
            emon.Port.TextAscii(t, "],\"trust\":");
            emon.Port.TextI32(t, emon.Port.CellsAt(tv, (i * Tvs) + 12));
            emon.Port.TextAscii(t, "}");
            i += 1;
        }
        emon.Port.TextAscii(t, "]");
        return 0;
    }
    public static int TtRecord(emon.Port.Cells tg, int k, int trust, emon.Port.Cells tv) {
        // Append table k's verdict row to the document's `tv`.
        int b = k * Tgs;
        int j = 0;
        emon.Port.CellsPush(tv, emon.Port.CellsAt(tg, b + 1));
        emon.Port.CellsPush(tv, emon.Port.CellsAt(tg, b));
        emon.Port.CellsPush(tv, emon.Port.CellsAt(tg, b + 2));
        emon.Port.CellsPush(tv, emon.Port.CellsAt(tg, b + 3));
        emon.Port.CellsPush(tv, emon.Port.CellsAt(tg, b + 10));
        emon.Port.CellsPush(tv, emon.Port.CellsAt(tg, b + 11));
        while (j < 6) {
            emon.Port.CellsPush(tv, emon.Port.CellsAt(tg, (b + 16) + j));
            j += 1;
        }
        emon.Port.CellsPush(tv, trust);
        return 0;
    }
    public static int TtGet(emon.Port.Cells tg, int k, int f) {
        // Field f of tagged table k.
        return emon.Port.CellsAt(tg, (k * Tgs) + f);
    }
    public static int TtSet(emon.Port.Cells tg, int k, int f, int v) {
        emon.Port.CellsSet(tg, (k * Tgs) + f, v);
        return 0;
    }
    public static int TtCget(emon.Port.Cells ta, int c, int f) {
        // Field f of tagged cell c.
        return emon.Port.CellsAt(ta, (c * Tas) + f);
    }
    public static int TtOr(emon.Port.Cells tg, int k, int f, int bits) {
        // Set bits in field f of tagged table k.
        int v = emon.Port.CellsAt(tg, (k * Tgs) + f) | bits;
        emon.Port.CellsSet(tg, (k * Tgs) + f, v);
        return 0;
    }
}
